mapper.select:

SELECT /*+ MAX_EXECUTION_TIME(${queryBudget.remainingMillis()}) */

  CAST(JSON_EXTRACT(r.values_json, CONCAT('$[', #{field.definition.ordinal}, ']')) AS CHAR CHARACTER SET utf8mb4) AS
  v${index}

FROM data_record r
WHERE r.enterprise_id = #{query.plan.collection.enterpriseId} AND r.collection_id = #{query.plan.collection.id}
AND r.generation = #{query.plan.generation}

ORDER BY

  
  
    ASC
    DESC
  
  ,

r.row_no ASC LIMIT #{rowLimit} OFFSET #{query.plan.offset}
